<section id="how-it-works" class="py-20 sm:py-24 bg-gray-50 dark:bg-gray-950 transition-colors duration-300">
    <div class="max-w-[1400px] mx-auto px-4 sm:px-6 lg:px-8">
        <div class="text-center mb-14">
            <span class="inline-block px-4 py-1.5 mb-5 text-[10px] font-bold text-[#0B5694] dark:text-blue-400 tracking-[0.18em] uppercase bg-[#0B5694]/8 dark:bg-blue-500/10 rounded-full">Application Process</span>
            <h2 class="text-3xl sm:text-4xl font-extrabold text-gray-900 dark:text-white tracking-tight">How to Apply for an Internship</h2>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
            {{-- Step 1 --}}
            <div class="bg-white dark:bg-gray-900 rounded-[32px] border border-gray-100 dark:border-gray-800 p-7 relative group transition-all duration-300 hover:shadow-lg">
                <span class="absolute top-4 right-5 text-5xl font-extrabold text-gray-100 dark:text-gray-800 select-none">1</span>
                <div class="w-12 h-12 bg-[#0B5694]/10 dark:bg-blue-500/10 rounded-[16px] flex items-center justify-center mb-5 relative">
                    <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0B5694" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
                </div>
                <h3 class="text-sm font-extrabold text-gray-900 dark:text-white tracking-tight mb-2 relative">Fill the Application</h3>
                <p class="text-xs text-gray-500 dark:text-gray-400 font-medium leading-relaxed relative">Complete the online onboarding form with your personal details, education background, and skills.</p>
            </div>

            {{-- Step 2 --}}
            <div class="bg-white dark:bg-gray-900 rounded-[32px] border border-gray-100 dark:border-gray-800 p-7 relative group transition-all duration-300 hover:shadow-lg">
                <span class="absolute top-4 right-5 text-5xl font-extrabold text-gray-100 dark:text-gray-800 select-none">2</span>
                <div class="w-12 h-12 bg-[#0B5694]/10 dark:bg-blue-500/10 rounded-[16px] flex items-center justify-center mb-5 relative">
                    <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0B5694" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2a4 4 0 0 1 4 4v2a4 4 0 0 1-8 0V6a4 4 0 0 1 4-4z"/><path d="M20 22v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/></svg>
                </div>
                <h3 class="text-sm font-extrabold text-gray-900 dark:text-white tracking-tight mb-2 relative">Get Matched to an Office</h3>
                <p class="text-xs text-gray-500 dark:text-gray-400 font-medium leading-relaxed relative">Our system matches you with the best-fit office based on your qualifications and institutional needs.</p>
            </div>

            {{-- Step 3 --}}
            <div class="bg-white dark:bg-gray-900 rounded-[32px] border border-gray-100 dark:border-gray-800 p-7 relative group transition-all duration-300 hover:shadow-lg">
                <span class="absolute top-4 right-5 text-5xl font-extrabold text-gray-100 dark:text-gray-800 select-none">3</span>
                <div class="w-12 h-12 bg-[#0B5694]/10 dark:bg-blue-500/10 rounded-[16px] flex items-center justify-center mb-5 relative">
                    <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0B5694" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                </div>
                <h3 class="text-sm font-extrabold text-gray-900 dark:text-white tracking-tight mb-2 relative">Start Your Internship</h3>
                <p class="text-xs text-gray-500 dark:text-gray-400 font-medium leading-relaxed relative">Begin your deployment at the assigned office. Log daily attendance and complete assigned tasks.</p>
            </div>

            {{-- Step 4 --}}
            <div class="bg-white dark:bg-gray-900 rounded-[32px] border border-gray-100 dark:border-gray-800 p-7 relative group transition-all duration-300 hover:shadow-lg">
                <span class="absolute top-4 right-5 text-5xl font-extrabold text-gray-100 dark:text-gray-800 select-none">4</span>
                <div class="w-12 h-12 bg-[#0B5694]/10 dark:bg-blue-500/10 rounded-[16px] flex items-center justify-center mb-5 relative">
                    <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0B5694" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="6"/><path d="M15.477 12.89 17 22l-5-3-5 3 1.523-9.11"/></svg>
                </div>
                <h3 class="text-sm font-extrabold text-gray-900 dark:text-white tracking-tight mb-2 relative">Earn Your Certificate</h3>
                <p class="text-xs text-gray-500 dark:text-gray-400 font-medium leading-relaxed relative">Complete the required hours and receive your digital internship certificate upon program completion.</p>
            </div>
        </div>
    </div>
</section>
